pub fn cloneRetopoGuide(guide: mesh_edit.RetopoGuide) ?mesh_edit.OwnedRetopoGuide {
    const live_bands = z3d.jalloc.dupe(u16, guide.live_bands) catch return null;
    const source_positions = z3d.jalloc.dupe(f32, guide.source_positions) catch {
        z3d.jalloc.free(live_bands);
        return null;
    };
    const source_bands = z3d.jalloc.dupe(u16, guide.source_bands) catch {
        z3d.jalloc.free(live_bands);
        z3d.jalloc.free(source_positions);
        return null;
    };
    return .{
        .live_bands = live_bands,
        .source_positions = source_positions,
        .source_bands = source_bands,
        .ghost_visible = guide.ghost_visible,
        .source_tracks_live = guide.source_tracks_live,
    };
}

pub fn restoreRetopoGuideAndDiscard(snap: *?z3d.JournalEntry) void {
    if (snap.*) |*entry| _ = z3d.journalInstallRetopoGuide(entry);
    z3d.journalDiscard(snap);
}

