}

pub fn clearRetopoBandPlan() bool {
    if (z3d.g_retopo_band_plan) |*plan| plan.deinit(std.heap.c_allocator) else return false;
    z3d.g_retopo_band_plan = null;
    return true;
}

pub fn clearRetopoManualBands() bool {
    z3d.g_retopo_pending_band = mesh_edit.RETOPO_BAND_UNASSIGNED;
    z3d.g_retopo_pending_band_generation = 0;
    if (z3d.g_retopo_manual_bands) |labels| std.heap.c_allocator.free(labels) else return false;
    z3d.g_retopo_manual_bands = null;
    return true;
}

pub fn clearRetopoSourceGhost() bool {
    if (z3d.g_retopo_source_ghost) |*ghost| ghost.deinit() else return false;
    z3d.g_retopo_source_ghost = null;
    return true;
}

pub fn captureRetopoSourceGhost(initial_bands: []const u16) bool {
    const positions = model_paint.positions() orelse return false;
    const face_count: usize = @intCast(model_paint.faceCount());
    if (face_count == 0 or initial_bands.len != face_count or positions.len < face_count * 9) return false;
    const frozen_positions = std.heap.c_allocator.dupe(f32, positions[0 .. face_count * 9]) catch return false;
    const frozen_bands = std.heap.c_allocator.dupe(u16, initial_bands) catch {
        std.heap.c_allocator.free(frozen_positions);
        return false;
    };
    _ = z3d.clearRetopoSourceGhost();
    z3d.g_retopo_source_ghost = .{
        .positions = frozen_positions,
        .bands = frozen_bands,
        .generation = z3d.g_edit_generation,
    };
    return true;
}

pub fn ensureRetopoSourceGhost(face_count: usize) bool {
    if (z3d.g_retopo_source_ghost) |*ghost| {
        return mesh_edit.retopoSourceGhostTracks(ghost.generation, z3d.g_edit_generation, ghost.bands.len, face_count);
    }
    const empty = std.heap.c_allocator.alloc(u16, face_count) catch return false;
    defer std.heap.c_allocator.free(empty);
    @memset(empty, mesh_edit.RETOPO_BAND_UNASSIGNED);
    return z3d.captureRetopoSourceGhost(empty);
}

pub const UV_ZONE_UNASSIGNED: u16 = mesh_edit.RETOPO_BAND_UNASSIGNED;

pub fn prepareZoneInheritance(row: *?[]u16, source_faces: []const u32) ?[]u16 {
    const current = row.* orelse return null;
    const next = std.heap.c_allocator.alloc(u16, source_faces.len) catch return null;
    if (!mesh_edit.inheritRetopoManualBands(current, source_faces, next)) {
        std.heap.c_allocator.free(next);
        return null;
    }
    return next;
}

pub fn prepareZoneCompaction(row: *?[]u16, removed: []const bool, kept_faces: usize) ?[]u16 {
    const current = row.* orelse return null;
    const next = std.heap.c_allocator.alloc(u16, kept_faces) catch return null;
    if (!mesh_edit.compactRetopoManualBands(current, removed, next)) {
        std.heap.c_allocator.free(next);
        return null;
    }
    return next;
}

pub fn prepareZoneAppend(row: *?[]u16, old_faces: usize, added_faces: usize, inherited: u16) ?[]u16 {
    const current = row.* orelse return null;
    if (current.len != old_faces) return null;
    const next = std.heap.c_allocator.alloc(u16, old_faces + added_faces) catch return null;
    @memcpy(next[0..old_faces], current);
    @memset(next[old_faces..], inherited);
    return next;
}

pub fn commitZoneCarry(row: *?[]u16, had_row: bool, prepared: *?[]u16) void {
    if (!had_row) return;
    if (row.*) |old| std.heap.c_allocator.free(old);
    row.* = prepared.*;
    prepared.* = null;
    if (row == &z3d.g_uv_zone) z3d.publishUvZoneMask();
}

pub fn prepareRetopoBandInheritance(source_faces: []const u32) ?[]u16 {
    return z3d.prepareZoneInheritance(&z3d.g_retopo_manual_bands, source_faces);
}

pub fn prepareRetopoBandCompaction(removed: []const bool, kept_faces: usize) ?[]u16 {
    return z3d.prepareZoneCompaction(&z3d.g_retopo_manual_bands, removed, kept_faces);
}

pub fn prepareRetopoBandAppend(old_faces: usize, added_faces: usize, inherited: u16) ?[]u16 {
    return z3d.prepareZoneAppend(&z3d.g_retopo_manual_bands, old_faces, added_faces, inherited);
}

// ── UV mask zones (req_4152) ─────────────────────────────────────────────────────
// Assigning faces to a zone groups them into ONE unfold chart for texturing. It does
// not merge, move, or regroup a single authored face — merging to get a clean UV also
// creases the shading and makes the result miserable to edit, which is why the mask
// exists instead.

pub fn uvZoneFaceCount() u32 {
    return z3d.g_edit_count / 3;
}

/// Hand the current zone row to the unfolder. Called after EVERY mutation of the row —
/// including the topology carry — so the chart layout can never be built from a row that
/// has since been renumbered, freed, or resized.
pub fn publishUvZoneMask() void {
    paint_islands_mod.setUvZoneMask(if (z3d.g_uv_zone) |row| row else null);
}

pub fn ensureUvZoneRow() ?[]u16 {
    const fc = z3d.uvZoneFaceCount();
    if (fc == 0) return null;
    if (z3d.g_uv_zone) |row| {
        if (row.len == fc) return row;
        std.heap.c_allocator.free(row);
        z3d.g_uv_zone = null;
    }
    const row = std.heap.c_allocator.alloc(u16, fc) catch return null;
    @memset(row, z3d.UV_ZONE_UNASSIGNED);
    z3d.g_uv_zone = row;
    z3d.publishUvZoneMask();
    return row;
}

/// Assign every selected face to `zone`, or release them with UV_ZONE_UNASSIGNED.
/// Returns how many faces changed. The mask is sized by the MESH and fully cleared —
/// sizing a selection mask by the paint layout is the bug that silently fed phantom
/// faces to the Face-to-N-gon resolver (req_4114).
pub fn uvZoneAssignSelection(zone: u16) u32 {
    if (!z3d.residentMutationAllowed(.uv_layout)) return 0;
    if (mesh_edit.mode() != .face) return 0;
    if (zone != z3d.UV_ZONE_UNASSIGNED and zone >= mesh_edit.RetopoBandTuning.max_bands) return 0;
    const fc = z3d.uvZoneFaceCount();
    if (fc == 0) return 0;
    const mask = std.heap.c_allocator.alloc(bool, @max(fc, model_paint.faceCount())) catch return 0;
    defer std.heap.c_allocator.free(mask);
    @memset(mask, false);
    if (mesh_edit.buildDeleteMask(mask) == 0) return 0;
    const row = z3d.ensureUvZoneRow() orelse return 0;
    var changed: u32 = 0;
    var face: u32 = 0;
    while (face < fc) : (face += 1) {
        if (!mask[face] or row[face] == zone) continue;
        row[face] = zone;
        changed += 1;
    }
    return changed;
}

/// The zone a face belongs to, or UV_ZONE_UNASSIGNED. Safe for any index.
pub fn uvZoneOfFace(face: u32) u16 {
    const row = z3d.g_uv_zone orelse return z3d.UV_ZONE_UNASSIGNED;
    return if (face < row.len) row[face] else z3d.UV_ZONE_UNASSIGNED;
}

/// Drop one zone entirely (its faces go back to unassigned). Returns faces released.
pub fn uvZoneDelete(zone: u16) u32 {
    if (!z3d.residentMutationAllowed(.uv_layout)) return 0;
    if (zone == z3d.UV_ZONE_UNASSIGNED) return 0;
    const row = z3d.g_uv_zone orelse return 0;
    var released: u32 = 0;
    for (row) |*slot| {
        if (slot.* != zone) continue;
        slot.* = z3d.UV_ZONE_UNASSIGNED;
        released += 1;
    }
    return released;
}

/// Face count per zone id, plus the unassigned tally, for the panel and the seat
/// percept. `out` is indexed by zone id; returns the number of ASSIGNED faces.
pub fn uvZoneCounts(out: []u32) u32 {
    @memset(out, 0);
    const row = z3d.g_uv_zone orelse return 0;
    var assigned: u32 = 0;
    for (row) |zone| {
        if (zone == z3d.UV_ZONE_UNASSIGNED) continue;
        assigned += 1;
        if (zone < out.len) out[zone] += 1;
    }
    return assigned;
}

pub fn uvZoneClearAll() bool {
    if (!z3d.residentMutationAllowed(.uv_layout)) return false;
    const row = z3d.g_uv_zone orelse return false;
    std.heap.c_allocator.free(row);
    z3d.g_uv_zone = null;
    z3d.publishUvZoneMask();
    return true;
}

/// Commit a prepared overlay only after the geometry + metadata transaction has
/// succeeded. Allocation failure degrades to clearing view state; it must never
/// reject or roll back authored geometry.
pub fn commitRetopoBandCarry(had_manual: bool, prepared: *?[]u16) void {
    if (!had_manual) return;
    z3d.commitZoneCarry(&z3d.g_retopo_manual_bands, true, prepared);
    _ = z3d.clearRetopoBandPlan();
}

pub fn clearRetopoBandPreview() bool {
    const planned = z3d.clearRetopoBandPlan();
    const manual = z3d.clearRetopoManualBands();
    const ghost = z3d.clearRetopoSourceGhost();
    return planned or manual or ghost;
}

/// Package persistence view of the teaching map. Planner output is intentionally
/// flattened to the same exact per-face labels as a manual map: cold continuation
/// needs the authored membership and frozen source, not the algorithm that first
/// proposed it.
pub fn meshRetopoGuideSnapshot() ?mesh_edit.RetopoGuide {
    const live_bands = if (z3d.g_retopo_manual_bands) |bands|
        bands
    else if (z3d.g_retopo_band_plan) |*plan|
        plan.faces
    else
        return null;
    const ghost = if (z3d.g_retopo_source_ghost) |*value| value else return null;
    if (live_bands.len != model_paint.faceCount() or ghost.bands.len == 0 or ghost.positions.len != ghost.bands.len * 9) return null;
    return .{
        .live_bands = live_bands,
        .source_positions = ghost.positions,
        .source_bands = ghost.bands,
        .ghost_visible = ghost.visible,
        .source_tracks_live = mesh_edit.retopoSourceGhostTracks(ghost.generation, z3d.g_edit_generation, ghost.bands.len, live_bands.len),
    };
}

/// Restore one validated package guide after the document mesh has loaded. The
/// live labels must match that exact saved topology; the frozen source may retain
/// the denser pre-retopology soup. Install everything or nothing.
pub fn meshRetopoGuideRestore(guide: mesh_edit.RetopoGuide) bool {
    const face_count: usize = @intCast(model_paint.faceCount());
    if (face_count == 0 or guide.live_bands.len != face_count or
        guide.source_bands.len == 0 or guide.source_positions.len != guide.source_bands.len * 9) return false;
    const live_bands = std.heap.c_allocator.dupe(u16, guide.live_bands) catch return false;
    const source_bands = std.heap.c_allocator.dupe(u16, guide.source_bands) catch {
        std.heap.c_allocator.free(live_bands);
        return false;
    };
    const source_positions = std.heap.c_allocator.dupe(f32, guide.source_positions) catch {
        std.heap.c_allocator.free(live_bands);
        std.heap.c_allocator.free(source_bands);
        return false;
    };

    _ = z3d.clearRetopoBandPreview();
    z3d.g_retopo_manual_bands = live_bands;
    z3d.g_retopo_source_ghost = .{
        .positions = source_positions,
        .bands = source_bands,
        // A guide captured before editing may keep accepting manual tint updates
        // after restart. Once topology froze the source, preserve that immutability.
        .generation = if (guide.source_tracks_live) z3d.g_edit_generation else z3d.g_edit_generation +% 1,
        .visible = guide.ghost_visible,
    };
    z3d.g_retopo_pending_band = mesh_edit.RETOPO_BAND_UNASSIGNED;
    z3d.g_retopo_pending_band_generation = 0;
    return true;
}
