/// Restore the persisted topology/atlas mismatch on a cold editor load. Only
/// explicit setPaintBase may clear this state; loading an old raster/program is
/// deliberately not an unlock path.
pub fn invalidatePaintLayout() void {
    if (!z3d.residentMutationAllowed(.uv_layout)) return;
    z3d.g_paint_layout_stale = true;
    z3d.g_paint_session = false;
}

pub fn setPaintSession(io: std.Io, environ: *const std.process.Environ.Map, on: bool) void {
    if (on and !z3d.residentMutationAllowed(.paint_session)) return;
    // Host enforcement: a cart bug, script, or stale UI state cannot enter paint
    // against a topology revision whose atlas has not been explicitly rebuilt.
    if (on and z3d.g_paint_layout_stale) return;
    if (on == z3d.g_paint_session) return;
    z3d.g_paint_session = on;
    if (on) {
        mesh_edit.clearSelection(); // restores tinted faces to true paint (atlas patches)
        mesh_edit.setMode(.none); // drops the face-mode dressing with it
    } else {
        // Leaving paint commits any half-open stroke as its own undo unit — the journal
        // must never carry a dangling gesture across sessions (req_2672).
        _ = z3d.paintStrokeEnd(io, environ);
    }
}
pub fn paintSessionActive() bool {
    return z3d.g_paint_session;
}
/// Pick the element under (mx,my) in the current mode (additive = shift toggle/extend),
/// fold it into the selection, and repaint. Returns the new selected count, -1 if no mesh.
pub fn meshEditPick(mx: f32, my: f32, additive: bool) i32 {
    if (z3d.g_paint_session) return -1; // paint owns the surface — no selection gestures (req_2662)
    if (!model_paint.hasTarget()) return -1;
    const cam = model_paint.Camera{ .eye = z3d.g_paint_eye, .target = z3d.g_paint_target, .fov_deg = z3d.g_paint_fov };
    if (z3d.g_historical_preview.active) |*specimen| {
        const px = z3d.vpLocalX(mx);
        const py = z3d.vpLocalY(my);
        var best_triangle: ?u32 = null;
        var best_depth = std.math.inf(f32);
        var triangle: u32 = 0;
        while (triangle < specimen.document.verts.len / 24) : (triangle += 1) {
            var projected: [3][3]f32 = undefined;
            var valid = true;
            for (0..3) |corner| {
                const base = @as(usize, triangle) * 24 + corner * 8;
                projected[corner] = model_paint.projectDepth(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, .{
                    specimen.document.verts[base + 0],
                    specimen.document.verts[base + 1],
                    specimen.document.verts[base + 2],
                }) orelse {
                    valid = false;
                    break;
                };
            }
            if (!valid) continue;
            const a = projected[0];
            const b = projected[1];
            const c = projected[2];
            const d0 = (px - b[0]) * (a[1] - b[1]) - (a[0] - b[0]) * (py - b[1]);
            const d1 = (px - c[0]) * (b[1] - c[1]) - (b[0] - c[0]) * (py - c[1]);
            const d2 = (px - a[0]) * (c[1] - a[1]) - (c[0] - a[0]) * (py - a[1]);
            const inside = (d0 >= 0 and d1 >= 0 and d2 >= 0) or (d0 <= 0 and d1 <= 0 and d2 <= 0);
            if (!inside) continue;
            const depth = (a[2] + b[2] + c[2]) / 3.0;
            if (depth < best_depth) {
                best_depth = depth;
                best_triangle = triangle;
            }
        }
        const hit = best_triangle orelse return 0;
        return @intCast(specimen.selectTriangle(hit, additive) catch return -1);
    }
    return mesh_edit.pick(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, z3d.vpLocalX(mx), z3d.vpLocalY(my), additive);
}

/// Ctrl+click pick (req_4271): in edge mode, select the whole edge path through the
/// clicked edge, cycling loop → ring → single edge on repeat clicks. Other modes fall
/// through to the ordinary pick inside mesh_edit.pathPick.
pub fn meshEditPathPick(mx: f32, my: f32, additive: bool) i32 {
    if (z3d.g_paint_session) return -1; // paint owns the surface — no selection gestures (req_2662)
    if (!model_paint.hasTarget()) return -1;
    if (z3d.g_historical_preview.active != null) return z3d.meshEditPick(mx, my, additive);
    const cam = model_paint.Camera{ .eye = z3d.g_paint_eye, .target = z3d.g_paint_target, .fov_deg = z3d.g_paint_fov };
    return mesh_edit.pathPick(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, z3d.vpLocalX(mx), z3d.vpLocalY(my), additive);
}

/// Ctrl+I (req_4271): invert the current mode's selection within the active scope.
pub fn meshEditInvert() i32 {
    if (z3d.g_paint_session) return -1;
    if (!model_paint.hasTarget()) return -1;
    return mesh_edit.invertSelection();
}

/// Live selection count in the current mode — the engine's cheap "is there anything
